// recipe: sound-log
// args: mode=s match=s
// returns: ok, mode, count, entries, error, detail
//
// Reads the one-shot recorder: every `Sound.Play` the game made since the batch started recording, newest last, optionally
// filtered by a clip-name substring. `mode=start` clears and arms it, `mode=read` answers what it holds, `mode=stop`
// disarms it. This is the listener-side fact a one-shot row needs — `audio-recent` can only see a clip that is mid-play
// when it is asked, so a landing between two round trips is invisible to it.
//
// ONE LINE ON PURPOSE: the client's evaluator takes one top-level expression.
((System.Func<string>)(() => { var mode = {{s:mode}}; var match = {{s:match}}; var assemblies = System.AppDomain.CurrentDomain.GetAssemblies(); var recorder = (System.Type)null; for (var i = 0; i < assemblies.Length; i++) { try { recorder = assemblies[i].GetType("CasualtiesUnknownOnline.Acceptance.SoundPlayRecorder", false); } catch { recorder = null; } if (recorder != null) { break; } } if (recorder == null) { return "{\"ok\":false,\"error\":\"recorder-not-loaded\"}"; } var flags = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic; if (mode == "start") { recorder.GetMethod("Start", flags).Invoke(null, null); return "{\"ok\":true,\"mode\":\"start\"}"; } if (mode == "stop") { recorder.GetMethod("Stop", flags).Invoke(null, null); return "{\"ok\":true,\"mode\":\"stop\"}"; } var since = recorder.GetMethod("Since", flags).Invoke(null, new object[] { match }); var list = since as System.Collections.IEnumerable; var builder = new System.Text.StringBuilder(); var count = 0; if (list != null) { foreach (var entry in list) { var type = entry.GetType(); var clip = type.GetProperty("Clip").GetValue(entry, null) as string; var time = type.GetProperty("Time").GetValue(entry, null); var position = type.GetProperty("Position").GetValue(entry, null); var vector = position is UnityEngine.Vector2 v ? v : UnityEngine.Vector2.zero; if (count > 0) { builder.Append(";"); } builder.Append(clip).Append("@").Append(System.Convert.ToSingle(time, System.Globalization.CultureInfo.InvariantCulture).ToString("0.00", System.Globalization.CultureInfo.InvariantCulture)).Append("(").Append(vector.x.ToString("0.0", System.Globalization.CultureInfo.InvariantCulture)).Append(",").Append(vector.y.ToString("0.0", System.Globalization.CultureInfo.InvariantCulture)).Append(")"); count++; if (count >= 40) { break; } } } var rawProp = recorder.GetProperty("RawCalls", flags); var raw = rawProp == null ? -1L : System.Convert.ToInt64(rawProp.GetValue(null, null), System.Globalization.CultureInfo.InvariantCulture); return "{\"ok\":true,\"raw\":" + raw.ToString(System.Globalization.CultureInfo.InvariantCulture) + ",\"mode\":\"" + mode + "\",\"count\":" + count.ToString(System.Globalization.CultureInfo.InvariantCulture) + ",\"entries\":\"" + builder.ToString() + "\"}"; }))()
